message:
Running command: set -euo pipefail
shopt -s dotglob nullglob
{
  echo "Scanning /workspace for potential session/cookie/storage artifacts...";
  find /workspace \
    -type f \
    \( -iname '*cookie*' -o -iname '*session*' -o -iname '*storage*' -o -name '*.sqlite' -o -name 'Local Storage*' -o -name 'Session Storage*' \) \
    -not -path '*/node_modules/*' \
    -not -path '*/.git/*' \
    -print 2>/dev/null || true;

  echo "\nScanning $HOME for browser/profile artifacts (limited depth)...";
  find "$HOME" \
    -maxdepth 4 \
    -type f \
    \( -iname '*cookie*' -o -iname '*session*' -o -iname '*storage*' -o -name '*.sqlite' -o -name 'Cookies' -o -name 'Cookies*' \) \
    -print 2>/dev/null || true;
} | sed 's#^#FOUND: #'

